import sys

def main():
    if len(sys.argv) <= 1:
        print("sayı yok")
        return
    numbers = list(map(int, sys.argv[1:]))
    average = sum(numbers) / len(numbers)
    print("{:.2f}".format(average))

if __name__ == "__main__":
    main()
